{
  "title":"Kế hoạch câu hỏi nâng cao về nhiệt động lực học và khí lý tưởng",
  "category":"categories.science",
  "plans":[
    {
      "id":"P31",
      "type":"multiple_choice",
      "recordIds":["F6"],
      "intent":"Tính áp suất cuối cùng của khí trong lốp khi nhiệt độ tăng từ 27 °C lên 54 °C, giả sử thể tích không đổi; yêu cầu lựa chọn đáp án đúng.",
      "reasoningSteps":["Chuyển đổi nhiệt độ Celsius sang Kelvin (T_K = T_°C+273) cho cả hai trạng thái","Áp dụng định luật khí lý tưởng ở thể tích không đổi P1/T1 = P2/T2 để tính P2"]
    },
    {
      "id":"P32",
      "type":"selection",
      "recordIds":["F7"],
      "intent":"Xác định các khẳng định đúng về khối lượng nitơ trong bình kín 12 L, áp suất 80 atm, nhiệt độ 17 °C, dựa trên tính toán n = PV/RT và mass = n·M; yêu cầu chọn tất cả đáp án đúng.",
      "reasoningSteps":["Tính số mol nitơ bằng công thức n = PV/(R·T) với R=0.082 atm·L/(mol·K) và T ở Kelvin","Nhân số mol với khối lượng mol 28 g/mol để có khối lượng nitơ, sau đó so sánh với các khẳng định"]
    },
    {
      "id":"P33",
      "type":"true_false",
      "recordIds":["F3"],
      "intent":"Khẳng định: \"Để tan và làm nóng 4 kg nước đá từ 0 °C lên 25 °C chỉ cần ít hơn 1 000 kJ nhiệt lượng.\"",
      "reasoningSteps":["Tính nhiệt lượng cần thiết Q = m·L_f + m·c·ΔT với L_f=3.4×10^6 J/kg và c=4180 J/(kg·K)","So sánh giá trị Q tính được (khoảng 1 700 kJ) với 1 000 kJ để xác định tính sai của khẳng định"],
      "targetTruthValue":"False"
    },
    {
      "id":"P34",
      "type":"short_answer",
      "recordIds":["F20"],
      "intent":"Xác định nhiệt độ (°C) của khí trong bình thép khi áp suất tăng từ 4 atm lên 4,5 atm, với thể tích không đổi; yêu cầu đưa ra giá trị nhiệt độ cuối cùng.",
      "reasoningSteps":["Chuyển đổi nhiệt độ ban đầu 70 °C sang Kelvin (T1=343 K)","Sử dụng P1/T1 = P2/T2 để tính T2, rồi chuyển lại sang Celsius (T2‑273)"]
    },
    {
      "id":"P35",
      "type":"multiple_choice",
      "recordIds":["F16"],
      "intent":"Tính áp suất bên trong xi lanh khi một học sinh 24 kg ngồi trên ghế, tổng khối lượng ghế và xi lanh 6 kg, piston có diện tích 30 cm², và áp suất khí quyển 10^5 Pa; yêu cầu chọn đáp án đúng.",
      "reasoningSteps":["Tính tổng lực trọng lượng F = (m_học sinh + m_ghế)·g = (24 kg+6 kg)·10 m/s²","Áp dụng công thức áp suất P = p₀ + F/S, trong đó S=30 cm²=3×10⁻³ m², để tìm áp suất nội bộ"]
    }
  ]
}
